#pragma once
#include "session_files.h"
#include <cmath>
#include <cstdio>
#include <cstring>
#include <vector>

// Runs while SDL's audio device is stopped, through the controller dispatcher and
// the same task-owned file service used by the interactive Virtual MK3.
inline bool desktop_readiness_workflow(groove::Engine& engine,groove::ProjectState& project,groove::Performance& perf,groove::SessionFiles& session,groove::IFileAccess& files) {
 using namespace groove;using T=ControllerInput::Type;
 float main[256]{},cue[256]{};bool ok=true;const char* stage="start";
 auto check=[&](bool v){if(!v && ok)std::fprintf(stderr,"readiness workflow failed: %s\n",stage);ok=ok && v;};
 auto input=[&](T type,unsigned index=0,int value=0,unsigned pressure=0){if(ok)check(perf.dispatch({type,uint8_t(index),value,uint16_t(pressure)}));};
 auto tick=[&](unsigned n=0){engine.render_ports(main,cue,nullptr,n);perf.poll();check(session.service());};
 auto mode=[&](UiMode m){input(T::Mode,0,int(m));};auto key=[&](unsigned n){input(T::SoftKey,n);tick();};
 auto pad=[&](unsigned n){unsigned hw=mk3::pad_logical(n);input(T::Pad,hw,0x10,3500);tick(128);input(T::Pad,hw,0x20);tick();};
 auto peak=[](const float* x){float p=0;for(unsigned i=0;i<256;++i){if(!std::isfinite(x[i]))return -1.0f;p=std::fmax(p,std::fabs(x[i]));}return p;};
 auto select=[&](const char* name){const auto& b=perf.browser();unsigned target=b.count;for(unsigned i=0;i<b.count;++i)if(!std::strcmp(b.entries[i].name,name)){target=i;break;}check(target<b.count);while(ok && perf.browser().cursor!=target){int delta=int(target)-int(perf.browser().cursor);if(delta>16)delta=16;if(delta< -16)delta=-16;input(T::Encoder,0,delta);}};
 stage="factory kit";mode(UiMode::Pad);key(4);check(perf.browser().library_list);select("Techno-01.mgxk");key(3);mode(UiMode::Pad);for(unsigned i=0;i<16 && ok;++i){pad(i);check(peak(main)>0.000001f);}input(T::Panic);tick(128);
 stage="browse sample";mode(UiMode::Browser);tick();key(1);select("assets");key(0);select("samples");key(0);select("demo-slices.wav");
 stage="cue preview";key(2);tick(128);check(peak(cue)>0.00001f && peak(main)<0.000001f);key(2);tick(128);
 stage="load sample";input(T::Track,0);check(perf.set_instrument(Instrument::Sampler));tick();key(3);mode(UiMode::Sampler);key(4);key(0);check(track_at(project,0,0).sample_edit.slice_count>1);key(1);input(T::Knob,0,1000);input(T::Knob,2,1000);tick();
 stage="map command (Top6 and confirm)";key(5);key(0);tick();stage="map state";for(unsigned i=0;i<16;++i){const auto t=track_at(project,0,i);check(t.instrument==Instrument::Sampler && t.sample_slices==t.sample_edit.slice_count && t.sample_slice<t.sample_slices && t.sample_slice==t.sample_edit.pads[i]%t.sample_slices);}
 stage="program and effects";mode(UiMode::Step);pad(0);pad(4);pad(8);pad(12);mode(UiMode::Effects);input(T::Knob,0,5000);input(T::Knob,3,5000);input(T::Knob,4,1000);input(T::Knob,6,5000);tick();mode(UiMode::Routing);input(T::Shift,0,1);input(T::Knob,3,1000);input(T::Knob,1,-10000);input(T::Shift,0,0);tick();check(project.routing.groups[0].members==1 && project.routing.groups[0].gain<1);auto expected=track_at(project,0,0);float delay=project.effects.delay_mix,reverb=project.effects.reverb_mix,decay=project.effects.reverb_decay,send=expected.reverb_send;check(expected.steps[0].enabled && delay>0 && reverb>0 && decay>0.5f && send>0);unsigned slot=expected.sample_slot;char path[96];check(copy_text(path,sizeof path,project.assets[slot].path));
 stage="live record";mode(UiMode::Routing);input(T::Knob,6,1000);input(T::Track,15);input(T::Shift,0,1);key(4);input(T::Shift,0,0);check(session.recording_busy());float virtual_input[256];for(unsigned i=0;i<128;++i){virtual_input[2*i]=0.2f;virtual_input[2*i+1]=-0.2f;}for(unsigned block=0;block<16 && ok;++block){engine.render_ports(main,cue,virtual_input,128);perf.poll();if(block%8==7)check(session.service());}key(4);for(unsigned n=0;n<32 && session.recording_busy() && ok;++n)tick();check(!session.recording_busy());tick();unsigned recorded_slot=track_at(project,0,15).sample_slot;check(project.assets[recorded_slot].metadata.frames==2048);input(T::Track,0);
 stage="bar record";input(T::Track,15);input(T::Play);tick();key(3);check(perf.record_quantized());input(T::Shift,0,1);key(4);input(T::Shift,0,0);for(unsigned block=0;block<800 && engine.live_record_state()!=2 && ok;++block){engine.render_ports(main,cue,virtual_input,128);perf.poll();check(session.service());}check(engine.live_record_state()==2);key(4);for(unsigned block=0;block<800 && session.recording_busy() && ok;++block){engine.render_ports(main,cue,virtual_input,128);perf.poll();check(session.service());}check(!session.recording_busy());tick();recorded_slot=track_at(project,0,15).sample_slot;check(project.assets[recorded_slot].metadata.frames==96000);input(T::Stop);tick();key(3);stage="take loop";mode(UiMode::Sampler);key(7);check(perf.notice()==UiNotice::LoopConfirm);key(0);check(track_at(project,0,15).steps[0].enabled && track_at(project,0,15).length==16);stage="overdub";unsigned original_slot=track_at(project,0,15).sample_slot;input(T::Play);tick();mode(UiMode::Routing);key(5);check(session.recording_busy());for(unsigned block=0;block<2200 && session.recording_busy() && ok;++block){engine.render_ports(main,cue,virtual_input,128);perf.poll();check(session.service());}check(!session.recording_busy());tick();unsigned dub_slot=track_at(project,0,15).sample_slot;check(dub_slot!=original_slot && project.assets[dub_slot].metadata.frames==96000);input(T::Undo);tick();check(track_at(project,0,15).sample_slot==original_slot);input(T::Redo);tick();check(track_at(project,0,15).sample_slot==dub_slot);input(T::Stop);tick();input(T::Track,0);
 stage="save";mode(UiMode::Project);key(0);check(perf.take_save_request());check(session.save("build/readiness-surface/song.mgxs"));
 stage="reload browser";mode(UiMode::Project);key(1);check(perf.mode()==UiMode::Browser);stage="reload select song";select("song.mgxs");stage="reload selected song";key(0);tick();stage="reload state";const auto restored=track_at(project,0,0);check(restored.steps[0].enabled && restored.steps[4].enabled && restored.sample_slot==slot && restored.sample_edit.slice_count==expected.sample_edit.slice_count && restored.sample_edit.start==expected.sample_edit.start && restored.sample_edit.speed==expected.sample_edit.speed && project.effects.delay_mix==delay && project.effects.reverb_mix==reverb && project.effects.reverb_decay==decay && restored.reverb_send==send && project.routing.groups[0].members==1 && project.routing.groups[0].gain<1 && track_at(project,0,15).steps[0].enabled && track_at(project,0,15).length==16 && track_at(project,0,15).sample_slot==dub_slot && !std::strcmp(project.assets[slot].path,path));
 stage="play restored project";mode(UiMode::Pad);input(T::Play);float maximum=0;std::vector<float> rendered(250*256);for(unsigned i=0;i<250 && ok;++i){tick(128);maximum=std::fmax(maximum,peak(main));for(unsigned j=0;j<256;++j)rendered[i*256+j]=main[j];}check(maximum>0.00001f);FileWriter output(files,"build/readiness-surface.wav");check(write_wav(output,rendered.data(),250*128) && output.finish());input(T::Stop);tick();
 stage="keyboard chord";check(perf.set_instrument(Instrument::FM));tick();check(track_at(project,0,0).instrument==Instrument::FM);mode(UiMode::Keyboard);input(T::Pad,12,0x10,3000);input(T::Pad,8,0x10,3000);tick(128);check(peak(main)>0.00001f);input(T::Pad,12,0x20);tick(128);check(peak(main)>0.00001f);input(T::Pad,8,0x20);tick();
 stage="step chord";mode(UiMode::Step);input(T::Shift,0,1);input(T::Pad,12,0x10,3000);input(T::Pad,12,0x20);mode(UiMode::Keyboard);input(T::Pad,8,0x10,3000);input(T::Pad,8,0x20);input(T::Pad,5,0x10,3000);input(T::Pad,5,0x20);input(T::Shift,0,0);tick();check(track_at(project,0,0).steps[0].chord[0]==64 && track_at(project,0,0).steps[0].chord[1]==69);check(session.save("build/readiness-surface-chord.mgxs"));check(session.load("build/readiness-surface-chord.mgxs"));tick();check(track_at(project,0,0).steps[0].chord[0]==64 && track_at(project,0,0).steps[0].chord[1]==69);mode(UiMode::Pad);input(T::Play);tick(128);check(peak(main)>0.00001f);input(T::Stop);tick();
 stage="note recording";mode(UiMode::Step);input(T::Shift,0,1);key(4);input(T::Shift,0,0);check(!project.ui.note_quantized);mode(UiMode::Keyboard);input(T::Control,6,0x40);input(T::Control,6,0);check(perf.note_recording());input(T::Play);tick(128);input(T::Pad,9,0x10,3200);tick(128);input(T::Pad,9,0x20);tick();check(track_at(project,0,0).steps[0].chord[2]==65 && track_at(project,0,0).steps[0].microtiming>0);int16_t recorded_timing=track_at(project,0,0).steps[0].microtiming;uint16_t recorded_gate=track_at(project,0,0).steps[0].gate;check(recorded_gate>=1 && recorded_gate<96);input(T::Control,6,0x40);input(T::Control,6,0);input(T::Stop);tick();check(session.save("build/readiness-note-record.mgxs"));check(session.load("build/readiness-note-record.mgxs"));tick();check(track_at(project,0,0).steps[0].chord[2]==65 && track_at(project,0,0).steps[0].gate==recorded_gate && track_at(project,0,0).steps[0].microtiming==recorded_timing && !project.ui.note_quantized);
 stage="replace recording";mode(UiMode::Step);input(T::Shift,0,1);key(5);input(T::Shift,0,0);check(project.ui.note_replace);input(T::Control,6,0x40);input(T::Control,6,0);input(T::Play);tick(128);tick(128);tick();check(!track_at(project,0,0).steps[0].enabled);input(T::Control,6,0x40);input(T::Control,6,0);input(T::Stop);tick();check(session.save("build/readiness-replace.mgxs"));check(session.load("build/readiness-replace.mgxs"));tick();check(project.ui.note_replace && !track_at(project,0,0).steps[0].enabled);
 stage="count-in";mode(UiMode::Step);input(T::Shift,0,1);key(5);key(2);input(T::Shift,0,0);check(!project.ui.note_replace && project.ui.count_in);input(T::Control,6,0x40);input(T::Control,6,0);input(T::Play);tick(128);check(perf.counting_in() && peak(cue)>0.00001f);for(unsigned i=0;i<1000 && perf.counting_in() && ok;++i)tick(128);check(!perf.counting_in());input(T::Control,6,0x40);input(T::Control,6,0);input(T::Stop);tick();check(session.save("build/readiness-count-in.mgxs"));check(session.load("build/readiness-count-in.mgxs"));tick();check(project.ui.count_in && !project.ui.click_main);
 if(ok){std::fprintf(stderr,"readiness workflow: factory 16 pads -> browse/preview -> chop/map -> steps/FX/group -> record -> save/reload -> audio PASS\n");}
 return ok;
}
